+++ b/package.json
@@ -3,13 +3,13 @@
   "version": "0.1.0",
   "type": "module",
   "bin": { "toolkit": "dist/cli.js" },
-  "engines": { "node": ">=22" },
+  "engines": { "node": ">=20" },
   "scripts": {
     "pretest": "node scripts/check-engines.mjs",
     "test": "node --test"
   },
   "dependencies": {
-    "commander": "^14.0.0",
-    "better-sqlite3": "^13.0.0"
+    "commander": "^11.1.0",
+    "better-sqlite3": "^9.0.0"
